import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"ホットキー設定","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. グローバル（Global）","slug":"_1-グローバル-global","link":"#_1-グローバル-global","children":[{"level":3,"title":"グローバルショートカット","slug":"グローバルショートカット","link":"#グローバルショートカット","children":[]},{"level":3,"title":"機能キー","slug":"機能キー","link":"#機能キー","children":[]},{"level":3,"title":"クイックナビゲーション（マウス操作）","slug":"クイックナビゲーション-マウス操作","link":"#クイックナビゲーション-マウス操作","children":[]},{"level":3,"title":"ホットキーを登録する","slug":"ホットキーを登録する","link":"#ホットキーを登録する","children":[]},{"level":3,"title":"お気に入りごとのホットキー","slug":"お気に入りごとのホットキー","link":"#お気に入りごとのホットキー","children":[]}]},{"level":2,"title":"2. プラグインアクション（Plugin Actions）","slug":"_2-プラグインアクション-plugin-actions","link":"#_2-プラグインアクション-plugin-actions","children":[]},{"level":2,"title":"3. プロセスブラックリスト（Process Blacklist）","slug":"_3-プロセスブラックリスト-process-blacklist","link":"#_3-プロセスブラックリスト-process-blacklist","children":[]}],"relativePath":"ja-JP/user-guide/settings/hotkeys-page.md","filePath":"ja-JP/user-guide/settings/hotkeys-page.md","lastUpdated":1791112464000}'),s={name:"ja-JP/user-guide/settings/hotkeys-page.md"};function i(n,o,a,c,d,g){return t(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="ホットキー設定" tabindex="-1">ホットキー設定 <a class="header-anchor" href="#ホットキー設定" aria-label="Permalink to &quot;ホットキー設定&quot;">​</a></h1><p>ホットキー設定画面では、Lertaro の全グローバル呼び出しキー、アプリ内ナビゲーションキー、プラグインアクションショートカット、およびプロセスブラックリストを一元管理します。画面上部には <strong>グローバル</strong>、<strong>プラグインアクション</strong>、<strong>プロセスブラックリスト</strong> の 3 つのタブが配置されています。</p><h2 id="_1-グローバル-global" tabindex="-1">1. グローバル（Global） <a class="header-anchor" href="#_1-グローバル-global" aria-label="Permalink to &quot;1. グローバル（Global）&quot;">​</a></h2><h3 id="グローバルショートカット" tabindex="-1">グローバルショートカット <a class="header-anchor" href="#グローバルショートカット" aria-label="Permalink to &quot;グローバルショートカット&quot;">​</a></h3><ul><li><strong>クイック検索の表示/非表示</strong>：専用のキー登録欄。<strong>修飾キーの 2 回連打モード</strong>（既定は <code>Ctrl</code> の 2 回連打、<code>Alt</code> や <code>Shift</code> にも設定可能）または <strong>通常のキー組み合わせ</strong>（例: <code>Alt+Space</code> など）に対応。</li><li><strong>既定でメインウィンドウを開く</strong>：チェックボックス（既定は無効）。有効にすると、グローバル呼び出しキーでクイックウィンドウではなくメインウィンドウを開きます。初回表示時は一度だけ前面とフォーカスを処理し、表示中で非アクティブなら再アクティブ化、すでにアクティブならもう一度押すと既定ではクイックウィンドウへ戻り、<strong>ショートカットの再入力でフルウィンドウを閉じる</strong>を有効にした場合はそのまま閉じます。自動的に最前面へ固定されることはありません。</li><li><strong>全画面アプリフォーカス時も応答する</strong>：チェックボックス（既定は無効）。有効にすると、フルスクリーンのゲームや動画プレイヤーがアクティブな場合でもホットキーに応答します。無効のときはゲーム操作を保護するためにキーをスルーします。</li><li><strong>クイックジャンプ（Quick Jump）</strong>：既定は <code>Ctrl+G</code>。ファイルダイアログ内で直前にファイラーで開いていたフォルダーへ移動します。</li><li><strong>クイックナビゲーションメニュー</strong>：既定ではショートカットなし。任意のグローバルショートカットを割り当てて階層型メニューを開けます。デスクトップや通常のアプリではデスクトップのコンテキストを使い、エクスプローラーやネイティブのファイルダイアログでは現在のウィンドウのコンテキストを使います。通常の前景保護でグローバルホットキーが抑止される場合でも、ファイラーとファイルダイアログは許可されます。</li></ul><h3 id="機能キー" tabindex="-1">機能キー <a class="header-anchor" href="#機能キー" aria-label="Permalink to &quot;機能キー&quot;">​</a></h3><p>カスタムの単一キーまたは組み合わせキーを登録できるコントロール群です。</p><ul><li><strong>次の項目 / 前の項目を選択</strong>：既定 <code>Ctrl+N</code> / <code>Ctrl+P</code>（方向キー <code>↓</code> / <code>↑</code> と同等）。</li><li><strong>結果ジャンプ修饰キー</strong>：既定 <code>Ctrl</code>、数字キー <code>1</code>–<code>9</code> と組み合わせて直接起動。</li><li><strong>アクションメニューを開く</strong>：既定 <code>Ctrl+O</code>（方向キー <code>→</code> と同等）。この 2 つはいずれもクイックウィンドウと、ファイルダイアログ外のインラインウィンドウで使えます。メインウィンドウでは同じメニューを右クリックまたは <code>Apps</code> キーで開きます。</li><li><strong>選択項目で検索語を補完</strong>：既定 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即時プレビュー</strong>：既定 <code>Alt+P</code>。</li><li><strong>前 / 次の検索履歴語</strong>：既定 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>現在の履歴語を削除</strong>：既定 <code>Ctrl+Delete</code>。</li><li><strong>メインウィンドウを開く</strong>：既定 <code>Ctrl+F</code>。</li><li><strong>LocalSend 画面を開く</strong>：既定 <code>Ctrl+S</code>。</li><li><strong>ウィンドウを固定（ピン留め）</strong>：既定 <code>Ctrl+T</code>。</li><li><strong>クイックパネルの表示/非表示</strong>：既定 <code>Ctrl+F2</code>。</li></ul><h3 id="クイックナビゲーション-マウス操作" tabindex="-1">クイックナビゲーション（マウス操作） <a class="header-anchor" href="#クイックナビゲーション-マウス操作" aria-label="Permalink to &quot;クイックナビゲーション（マウス操作）&quot;">​</a></h3><ul><li><strong>余白部分で左ダブルクリック</strong>：チェックボックス（<strong>既定は無効</strong>）。デスクトップやエクスプローラーの余白ダブルクリックでメニューを表示。</li><li><strong>余白部分で中クリック</strong>：チェックボックス（既定で有効）。デスクトップやエクスプローラー、ファイルダイアログで中クリックしてメニューを表示。</li></ul><p>左ダブルクリックの形を受け付けるのはデスクトップとエクスプローラーだけで、サードパーティ製ファイラーは中クリックのみです。どちらのトリガーも、ポインターが Lertaro 自身のウィンドウ上にある間はスキップされます。また、ブラックリストや全画面によって通常ならグローバルなトリガーが無効化される状況でも、ファイラーとダイアログに対してはどちらも生きたまま維持されます。</p><h3 id="ホットキーを登録する" tabindex="-1">ホットキーを登録する <a class="header-anchor" href="#ホットキーを登録する" aria-label="Permalink to &quot;ホットキーを登録する&quot;">​</a></h3><p>キー入力は背後のアプリではなく登録欄へ送られます。そのため登録控件そのものが一連のジェスチャーになっています。</p><ul><li><strong><code>Escape</code></strong>：登録を中止して値をクリアします。「破棄して元に戻す」は存在せず、押した瞬間に欄は空になります。</li><li><strong><code>✕</code></strong>：欄をクリアします。<strong><code>↺</code></strong>：その行の出荷時既定値を復元します。2 つのうち表示されるのは常にどちらか 1 つだけで、組み合わせが設定されている間はクリア、空になったあとは復元になります。</li><li><strong>修飾キー単体</strong>（<code>Ctrl</code>、<code>Alt</code>、<code>Shift</code>）は、単体で意味を持つ行でのみ受理されます。それは呼び出しホットキー（2 回連打方式になるもの）と結果ジャンプの修飾キーです。通常の組み合わせ用の行で修飾キーだけを押して離すと、発火のしようのない値を保存する代わりに、その行は<strong>クリア</strong>されます。</li><li><strong>Windows 予約の組み合わせ</strong>（<code>Win+E</code>、<code>Win+D</code> など）は拒否されます。値は空へ強制変換されるため、欄は単に空白になります。</li><li><strong>重複の検出はありません。</strong> 2 つの行に同じ組み合わせを登録しても警告は何も出ません。お気に入り項目のホットキーだけが重複または OS に拒否された組み合わせを報告しますが、それも適用したあとになってからです。</li></ul><h3 id="お気に入りごとのホットキー" tabindex="-1">お気に入りごとのホットキー <a class="header-anchor" href="#お気に入りごとのホットキー" aria-label="Permalink to &quot;お気に入りごとのホットキー&quot;">​</a></h3><p>すべてのお気に入り（<a href="./favorites.html"><strong>設定 → お気に入り</strong></a>）には、それぞれ専用の <strong>OS レベルのグローバル</strong>ホットキーを登録できます。Lertaro にウィンドウが 1 つも開かれていないときでも機能し、フォアグラウンドのファイラーをそのフォルダーへ移動させます。上の登録欄と異なり、修飾キーが必須で、修飾キー単体は拒否され、<code>F12</code> は使えません。</p><h2 id="_2-プラグインアクション-plugin-actions" tabindex="-1">2. プラグインアクション（Plugin Actions） <a class="header-anchor" href="#_2-プラグインアクション-plugin-actions" aria-label="Permalink to &quot;2. プラグインアクション（Plugin Actions）&quot;">​</a></h2><p>各プラグインが登録したアクションショートカット（例: パスコピー <code>Ctrl+Shift+C</code>、名前をコピー <code>Shift+C</code>、切り取り <code>Ctrl+X</code>、コピー <code>Ctrl+C</code>、貼り付け <code>Ctrl+V</code>、削除 <code>Delete</code>、完全削除 <code>Shift+Delete</code> など）が一覧表示されます。</p><ul><li><strong>プラグインごとのグループ分け</strong>：提供元のプラグインごとに整理されています。</li><li><strong>個別の再登録</strong>：各アクションに専用の登録欄があり、新しいキーを押すだけで変更可能です。</li></ul><h2 id="_3-プロセスブラックリスト-process-blacklist" tabindex="-1">3. プロセスブラックリスト（Process Blacklist） <a class="header-anchor" href="#_3-プロセスブラックリスト-process-blacklist" aria-label="Permalink to &quot;3. プロセスブラックリスト（Process Blacklist）&quot;">​</a></h2><p>特定のアプリがフォアグラウンドにある際、Lertaro のホットキーやマウス操作を無効化するリストです。</p><ul><li><strong>大文字小文字の区別なし</strong>：<code>game.exe</code> または <code>game</code> のどちらでも一致します。</li><li><strong>個別追加</strong>：プロセス名を入力して <strong>プロセスを追加</strong> をクリック。</li><li><strong>テキストでの一括管理</strong>：<strong>テキスト生成</strong> で現在のリストを複数行テキストとしてエクスポートしたり、貼り付けて <strong>リストに適用</strong> で一括更新できます。</li><li><strong>ファイルダイアログの自動除外</strong>：ブラックリスト内のアプリであっても、Windows 標準のファイルダイアログが表示されているときはインライン検索やクイックナビゲーションが正常に動作します。</li></ul>',22)])])}const p=e(s,[["render",i]]);export{u as __pageData,p as default};
